function computeCodSplit(lineTotal, platformFee, deliveryFee, depositPercent) {
  const total = Math.max(0, lineTotal) + Math.max(0, platformFee) + Math.max(0, deliveryFee)
  if (total <= 0) return { deposit: 0, balanceDue: 0 }
  const pct = Number.isFinite(depositPercent) && depositPercent > 0 ? depositPercent : 0
  if (pct <= 0) return { deposit: 0, balanceDue: total }
  const byPercent = Math.ceil((Math.max(0, lineTotal) * pct) / 100)
  const deposit = Math.min(total, Math.max(byPercent, Math.max(0, platformFee)))
  return { deposit, balanceDue: total - deposit }
}
const cases = [
  ['typical: 500 produce, 25 fee(5%), 30 delivery, 10%', 500, 25, 30, 10],
  ['small order where 10% < platform fee', 100, 25, 30, 10],
  ['no platform fee', 500, 0, 0, 10],
  ['deposit disabled (0%)', 500, 25, 30, 0],
  ['rounding: 333 produce', 333, 17, 30, 10],
  ['tiny order', 20, 1, 0, 10],
  ['deposit % huge (100%)', 500, 25, 30, 100],
]
let fail = 0
for (const [name, t, pf, df, pct] of cases) {
